DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `go_down_product_id` bigint(20) unsigned NOT NULL,
  `product_code` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `packet_size` double NOT NULL,
  `unit_id` bigint(20) unsigned NOT NULL,
  `quantity` double NOT NULL,
  `buying_price` float(10,5) NOT NULL DEFAULT 0.00000,
  `selling_price` double NOT NULL,
  `gst` double NOT NULL DEFAULT 0,
  `description` longtext DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_slug_unique` (`slug`),
  KEY `products_go_down_product_id_foreign` (`go_down_product_id`),
  KEY `products_unit_id_foreign` (`unit_id`),
  CONSTRAINT `products_go_down_product_id_foreign` FOREIGN KEY (`go_down_product_id`) REFERENCES `go_down_products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=186 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


